                <Select>
                  <SelectTrigger className="text-black">
                    <SelectValue
                      placeholder={filter.name}
                      className="text-black"
                    />
                  </SelectTrigger>
                  <SelectContent>
                    {filter.values.map((value) => (
                      <SelectItem key={value} value={value}>
                        {value}
